  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, status, created_by, updated_by) VALUES (gen_random_uuid(), 'TUT-KOMPUTER13-001', 'baaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa', $txt$Password Manager: Amankan Semua Akunmu$txt$, 'password-manager-amankan-akun', $txt$Panduan memasang password manager: satu master password untuk mengamankan ratusan akun.$txt$, 'id', 8, 'Madevi', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'DRAFT', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'f7125028-187e-44e0-b95b-88b69b8d5c9a') ON CONFLICT (business_code) DO NOTHING RETURNING id INTO v_tut_komputer13_001;
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_tut_komputer13_001, 'HEADING', 0, jsonb_build_object('text', $txt$Masalah: Ratusan Akun, Satu Password yang Sama$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_tut_komputer13_001, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Rata-rata pengguna internet memiliki puluhan hingga ratusan akun: email, media sosial, bank, belanja, pekerjaan. Kebanyakan memakai satu atau dua password yang sama untuk semuanya. Sekali satu situs bocor, semua akun ikut terancam. Menghafal password berbeda untuk setiap akun adalah mustahil bagi otak manusia — di sinilah password manager menyelamatkan.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_tut_komputer13_001, 'HEADING', 2, jsonb_build_object('text', $txt$Penjelasan: Apa Itu Password Manager$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_tut_komputer13_001, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Password manager adalah aplikasi yang menyimpan semua password Anda dalam sebuah brankas terenkripsi, dikunci oleh satu master password yang kuat. Ia bisa membuat password acak yang panjang untuk setiap akun, mengisi otomatis saat login, dan menyinkron antar perangkat. Datanya dienkripsi dengan standar seperti AES-256, sehingga penyedia layanan pun tidak bisa membaca password Anda.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_tut_komputer13_001, 'HEADING', 4, jsonb_build_object('text', $txt$Alat yang Dibutuhkan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_tut_komputer13_001, 'LIST', 5, jsonb_build_object('items', ARRAY[$txt$Komputer atau HP dengan koneksi internet$txt$,$txt$Satu password manager pilihan: Bitwarden (gratis, open source), 1Password, atau pengelola bawaan browser$txt$,$txt$Autentikasi dua faktor (2FA) aktif di email utama$txt$,$txt$Catatan darurat: kode pemulihan yang dicetak di kertas$txt$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_tut_komputer13_001, 'HEADING', 6, jsonb_build_object('text', $txt$Langkah Memasang Password Manager$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_tut_komputer13_001, 'LIST', 7, jsonb_build_object('items', ARRAY[$txt$Unduh password manager pilihan dari situs resminya — jangan dari iklan atau tautan acak.$txt$,$txt$Buat master password: minimal 5 kata acak yang mudah diingat Anda, misalnya frasa unik. Tulis di kertas, simpan di tempat aman.$txt$,$txt$Aktifkan autentikasi dua faktor pada akun password manager Anda.$txt$,$txt$Pasang ekstensi browser dan aplikasi HP-nya, lalu login dengan akun yang sama.$txt$,$txt$Mulai pindahkan akun penting dulu: email, bank, media sosial, belanja. Gunakan fitur impor bila tersedia.$txt$,$txt$Untuk setiap akun, buat password baru yang acak (16+ karakter) memakai generator bawaan.$txt$,$txt$Hapus catatan password lama di kertas/notepad HP setelah semuanya tersimpan dengan benar.$txt$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_tut_komputer13_001, 'HEADING', 8, jsonb_build_object('text', $txt$Risiko dan Jebakannya$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_tut_komputer13_001, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Risiko terbesar: lupa master password berarti kehilangan akses ke seluruh brankas — tidak ada tombol lupa password yang bisa ditembus karena enkripsi nol-pengetahuan. Mitigasinya: simpan kode pemulihan di kertas di tempat aman dan beritahu satu orang terpercaya. Jangan simpan master password di email atau catatan HP tanpa proteksi. Hindari password manager bajakan atau ekstensi browser tidak resmi.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_tut_komputer13_001, 'HEADING', 10, jsonb_build_object('text', $txt$Penyelesaian dan Tindak Lanjut$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_tut_komputer13_001, 'PARAGRAPH', 11, jsonb_build_object('text', $txt$Dengan satu master password yang kuat plus 2FA, Anda kini jauh lebih aman daripada 99 persen pengguna internet. Periksa hasil: setiap akun penting punya password unik 16+ karakter, tidak ada yang dipakai ulang; aktifkan pemindai keamanan di password manager untuk menemukan password lemah; pastikan sinkronisasi antar perangkat berjalan. Tindak lanjut: ganti password akun-akun tersisa secara bertahap, aktifkan 2FA di semua akun penting, dan biasakan tidak pernah memakai password yang sama di dua tempat berbeda.$txt$));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, status, created_by, updated_by) VALUES (gen_random_uuid(), 'TUT-KESEHATAN21-001', 'b5555555-5555-5555-5555-555555555555', $txt$Sakit Perut: Penyebab Umum dan Penanganan$txt$, 'sakit-perut-penyebab-umum', $txt$Penyebab umum sakit perut, penanganan mandiri di rumah, dan tanda bahaya kapan harus ke dokter.$txt$, 'id', 7, 'Madevi', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'DRAFT', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'f7125028-187e-44e0-b95b-88b69b8d5c9a') ON CONFLICT (business_code) DO NOTHING RETURNING id INTO v_tut_kesehatan21_001;
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_tut_kesehatan21_001, 'HEADING', 0, jsonb_build_object('text', $txt$Masalah: Sakit Perut Tiba-tiba$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_tut_kesehatan21_001, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Sakit perut adalah keluhan yang sangat umum — hampir semua orang mengalaminya. Penyebabnya bisa sepele seperti masuk angin atau makan terlalu pedas, bisa juga tanda kondisi yang perlu perhatian medis. Informasi ini bersifat umum dan bukan pengganti nasihat dokter; bila ragu, konsultasikan ke dokter atau puskesmas.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_tut_kesehatan21_001, 'HEADING', 2, jsonb_build_object('text', $txt$Penjelasan: Penyebab Umum Sakit Perut$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_tut_kesehatan21_001, 'LIST', 3, jsonb_build_object('items', ARRAY[$txt$Gangguan pencernaan ringan: makan berlebihan, pedas, berlemak, atau tidak teratur.$txt$,$txt$Masuk angin dan kembung: gas menumpuk di lambung atau usus.$txt$,$txt$Keracunan makanan ringan: mual setelah makan makanan basi atau terkontaminasi.$txt$,$txt$Diare atau sembelit: gangguan pola buang air besar.$txt$,$txt$Maag (dispepsia): nyeri ulu hati setelah makan atau telat makan.$txt$,$txt$Infeksi saluran cerna: diare berair, kadang disertai demam.$txt$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_tut_kesehatan21_001, 'HEADING', 4, jsonb_build_object('text', $txt$Persiapan Pertolongan Mandiri$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_tut_kesehatan21_001, 'LIST', 5, jsonb_build_object('items', ARRAY[$txt$Air putih hangat untuk menjaga hidrasi$txt$,$txt$Teh jahe atau air hangat untuk rasa mual ringan$txt$,$txt$Obat umum di rumah bila tersedia: antasida untuk maag, oralit bila diare$txt$,$txt$Catat pola: kapan mulai, lokasi nyeri, dan gejala penyerta$txt$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_tut_kesehatan21_001, 'HEADING', 6, jsonb_build_object('text', $txt$Langkah Penanganan di Rumah$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_tut_kesehatan21_001, 'LIST', 7, jsonb_build_object('items', ARRAY[$txt$Beristirahat dan hindari makan berat selama 2-3 jam pertama.$txt$,$txt$Minum air putih sedikit-sedikit tapi sering.$txt$,$txt$Bila mual, coba teh jahe hangat atau air hangat.$txt$,$txt$Bila nyeri ulu hati, makanlah dalam porsi kecil dan hindari makanan pedas, asam, dan kopi.$txt$,$txt$Bila diare, minum oralit untuk mengganti cairan dan elektrolit.$txt$,$txt$Catat gejala: intensitas nyeri, frekuensi muntah/diare, dan ada tidaknya demam.$txt$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_tut_kesehatan21_001, 'HEADING', 8, jsonb_build_object('text', $txt$Risiko: Kapan Harus ke Dokter$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_tut_kesehatan21_001, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Segera ke dokter atau IGD bila: nyeri perut hebat dan mendadak, muntah darah atau BAB berdarah/hitam, demam tinggi yang tidak turun, perut kaku dan sangat nyeri saat disentuh, tanda dehidrasi (jarang buang air kecil, mulut kering, pusing), atau gejala berlangsung lebih dari 2 hari tanpa membaik.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_tut_kesehatan21_001, 'HEADING', 10, jsonb_build_object('text', $txt$Penyelesaian dan Tindak Lanjut$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_tut_kesehatan21_001, 'PARAGRAPH', 11, jsonb_build_object('text', $txt$Sakit perut ringan umumnya sembuh sendiri dengan istirahat dan hidrasi — gejala mereda dalam 24-48 jam dan pola BAB kembali normal tanpa tanda bahaya. Tindak lanjut: jaga pola makan teratur, cuci tangan sebelum makan, dan simpan makanan dengan benar. Bila sakit perut sering kambuh, konsultasikan ke dokter untuk mencari penyebab pastinya — artikel ini hanya informasi umum, bukan diagnosis.$txt$));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, status, created_by, updated_by) VALUES (gen_random_uuid(), 'EXP-ANTROPOLOGI12-001', 'c8888888-8888-8888-8888-888888888888', $txt$Suku Mentawai: Penjaga Tato Tertua di Dunia$txt$, 'suku-mentawai-tato-tertua', $txt$Mengenal Suku Mentawai: tato titi tertua di dunia, sikerei, rumah uma, dan filosofi Arat Sabulungan.$txt$, 'id', 8, 'Madevi', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'DRAFT', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'f7125028-187e-44e0-b95b-88b69b8d5c9a') ON CONFLICT (business_code) DO NOTHING RETURNING id INTO v_exp_antropologi12_001;
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_exp_antropologi12_001, 'HEADING', 0, jsonb_build_object('text', $txt$Siapa Suku Mentawai$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_exp_antropologi12_001, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Suku Mentawai mendiami Kepulauan Mentawai di lepas pantai barat Sumatra, Provinsi Sumatra Barat. Mereka adalah salah satu suku tertua di Indonesia dengan kebudayaan yang nyaris tak berubah selama ratusan tahun, hidup selaras dengan hutan hujan tropis yang menjadi rumah sekaligus sumber kehidupan mereka.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_exp_antropologi12_001, 'HEADING', 2, jsonb_build_object('text', $txt$Tato Tertua di Dunia$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_exp_antropologi12_001, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Tato Mentawai (titi) termasuk salah satu tradisi tato tertua di dunia yang masih hidup. Tato dibuat dengan alat tradisional dari paku kayu dan arang, menghiasi hampir seluruh tubuh pria dewasa. Motifnya bukan hiasan semata — setiap pola menandai identitas klan, status kedewasaan, dan perjalanan spiritual pemiliknya.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_exp_antropologi12_001, 'HEADING', 4, jsonb_build_object('text', $txt$Sikerei: Dukun dan Penjaga Tradisi$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_exp_antropologi12_001, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Sikerei adalah dukun sekaligus tokoh spiritual Mentawai. Ia memimpin ritual, mengobati orang sakit dengan ramuan hutan, dan menjadi penghubung antara manusia dan arwah (simagere). Sikerei mudah dikenali dari tubuhnya yang penuh tato dan mahkota bunga.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_exp_antropologi12_001, 'HEADING', 6, jsonb_build_object('text', $txt$Uma: Rumah Panjang Komunal$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_exp_antropologi12_001, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Uma adalah rumah panggung panjang tempat tinggal satu klan besar. Di sinilah semua kegiatan berlangsung: makan bersama, musyawarah, ritual, hingga pengasapan mayat. Arsitekturnya dari kayu dan daun sagu mencerminkan filosofi hidup komunal yang kuat.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_exp_antropologi12_001, 'HEADING', 8, jsonb_build_object('text', $txt$Kesimpulan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_exp_antropologi12_001, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Suku Mentawai adalah penjaga hidup salah satu kebudayaan tertua di Nusantara. Melestarikan mereka berarti melestarikan cara pandang alternatif tentang hubungan manusia dan alam — sesuatu yang tidak bisa digantikan oleh teknologi apa pun.$txt$));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, status, created_by, updated_by) VALUES (gen_random_uuid(), 'EXP-KIMIA19-001', 'c4444444-4444-4444-4444-444444444444', $txt$Besi: Logam yang Menopang Peradaban$txt$, 'besi-logam-peradaban', $txt$Sifat, sejarah, dan peran besi: dari Zaman Besi hingga hemoglobin dalam darahmu.$txt$, 'id', 8, 'Madevi', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'DRAFT', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'f7125028-187e-44e0-b95b-88b69b8d5c9a') ON CONFLICT (business_code) DO NOTHING RETURNING id INTO v_exp_kimia19_001;
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_exp_kimia19_001, 'HEADING', 0, jsonb_build_object('text', $txt$Logam yang Mengubah Peradaban$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_exp_kimia19_001, 'PARAGRAPH', 1, jsonb_build_object('text', $txt$Besi (Fe, ferrum) adalah unsur logam paling melimpah di Bumi — inti planet kita sebagian besar terdiri dari besi. Namun yang membuatnya istimewa adalah perannya dalam sejarah manusia: Zaman Besi menandai lompatan peradaban dari perkakas batu dan perunggu ke alat yang jauh lebih kuat dan murah.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_exp_kimia19_001, 'HEADING', 2, jsonb_build_object('text', $txt$Sifat Fisika dan Kimia Besi$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_exp_kimia19_001, 'LIST', 3, jsonb_build_object('items', ARRAY[$txt$Logam berwarna abu-abu keperakan, mengilap, dan dapat ditempa.$txt$,$txt$Bersifat magnetik — salah satu dari sedikit unsur yang demikian.$txt$,$txt$Mudah berkarat (oksidasi) bila terkena air dan udara.$txt$,$txt$Titik lebur 1.538 derajat Celsius.$txt$,$txt$Dapat membentuk paduan (alloy) dengan sifat yang sangat bervariasi.$txt$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_exp_kimia19_001, 'HEADING', 4, jsonb_build_object('text', $txt$Dari Besi ke Baja$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_exp_kimia19_001, 'PARAGRAPH', 5, jsonb_build_object('text', $txt$Besi murni relatif lunak. Keajaiban terjadi saat besi dicampur sedikit karbon (0,2-2,1 persen) menjadi baja — jauh lebih keras dan kuat. Tambahan kromium menghasilkan baja tahan karat (stainless steel). Inilah fondasi konstruksi modern: gedung pencakar langit, jembatan, rel kereta, dan kapal raksasa.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_exp_kimia19_001, 'HEADING', 6, jsonb_build_object('text', $txt$Besi dalam Tubuh Manusia$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_exp_kimia19_001, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Besi adalah mineral esensial: ia menjadi inti hemoglobin, protein dalam sel darah merah yang mengangkut oksigen ke seluruh tubuh. Kekurangan zat besi menyebabkan anemia — lemas, pucat, dan mudah lelah. Sumbernya: daging merah, hati, bayam, dan kacang-kacangan.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_exp_kimia19_001, 'HEADING', 8, jsonb_build_object('text', $txt$Kesimpulan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_exp_kimia19_001, 'PARAGRAPH', 9, jsonb_build_object('text', $txt$Dari pedang zaman kuno hingga jembatan modern, dari darah di tubuh hingga inti planet — besi adalah logam yang benar-benar menopang peradaban. Memahaminya berarti memahami fondasi dunia material tempat kita hidup.$txt$));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, status, created_by, updated_by) VALUES (gen_random_uuid(), 'SCH-SMP-BIO7-001', 'd4444444-4444-4444-4444-444444444444', $txt$IPA Kelas 7: Energi dan Perubahannya$txt$, 'ipa-kelas-7-energi', $txt$Materi IPA kelas 7: pengertian energi, bentuk-bentuknya, perhitungan, dan sumber energi.$txt$, 'id', 9, 'Madevi', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'DRAFT', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'f7125028-187e-44e0-b95b-88b69b8d5c9a') ON CONFLICT (business_code) DO NOTHING RETURNING id INTO v_sch_smp_bio7_001;
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_sch_smp_bio7_001, 'HEADING', 0, jsonb_build_object('text', $txt$Tujuan Pembelajaran$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_sch_smp_bio7_001, 'LIST', 1, jsonb_build_object('items', ARRAY[$txt$Menjelaskan pengertian energi dan satuannya$txt$,$txt$Mengidentifikasi bentuk-bentuk energi$txt$,$txt$Menjelaskan perubahan bentuk energi dalam kehidupan sehari-hari$txt$,$txt$Menghitung energi potensial dan energi kinetik sederhana$txt$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_sch_smp_bio7_001, 'HEADING', 2, jsonb_build_object('text', $txt$Pengertian Energi$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_sch_smp_bio7_001, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Energi adalah kemampuan untuk melakukan usaha (kerja). Segala aktivitas — berjalan, berpikir, menyalakan lampu — membutuhkan energi. Satuan energi dalam SI adalah joule (J). Hukum kekekalan energi menyatakan energi tidak dapat diciptakan atau dimusnahkan, hanya berubah bentuk.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_sch_smp_bio7_001, 'HEADING', 4, jsonb_build_object('text', $txt$Bentuk-bentuk Energi$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_sch_smp_bio7_001, 'LIST', 5, jsonb_build_object('items', ARRAY[$txt$Energi kinetik: energi benda yang bergerak. Rumus: Ek = 1/2 x m x v^2.$txt$,$txt$Energi potensial: energi karena posisi/ketinggian. Rumus: Ep = m x g x h.$txt$,$txt$Energi kalor (panas): dari api, gesekan, atau Matahari.$txt$,$txt$Energi listrik: mengalir melalui kabel.$txt$,$txt$Energi kimia: tersimpan dalam makanan, baterai, dan bahan bakar.$txt$,$txt$Energi cahaya dan bunyi.$txt$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_sch_smp_bio7_001, 'HEADING', 6, jsonb_build_object('text', $txt$Contoh Perhitungan$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_sch_smp_bio7_001, 'PARAGRAPH', 7, jsonb_build_object('text', $txt$Contoh 1: Sebuah batu bermassa 2 kg dijatuhkan dari ketinggian 5 m (g = 10 m/s^2). Energi potensialnya: Ep = m x g x h = 2 x 10 x 5 = 100 joule. Contoh 2: Mobil bermassa 1.000 kg bergerak 20 m/s. Energi kinetiknya: Ek = 1/2 x 1.000 x 20^2 = 200.000 joule.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_sch_smp_bio7_001, 'HEADING', 8, jsonb_build_object('text', $txt$Perubahan Bentuk Energi$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_sch_smp_bio7_001, 'LIST', 9, jsonb_build_object('items', ARRAY[$txt$Setrika listrik: energi listrik menjadi energi kalor.$txt$,$txt$Kipas angin: energi listrik menjadi energi gerak.$txt$,$txt$Fotosintesis: energi cahaya menjadi energi kimia.$txt$,$txt$Tubuh manusia: energi kimia dari makanan menjadi energi gerak dan kalor.$txt$,$txt$PLTA: energi potensial air menjadi energi listrik.$txt$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_sch_smp_bio7_001, 'HEADING', 10, jsonb_build_object('text', $txt$Latihan Soal$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_sch_smp_bio7_001, 'LIST', 11, jsonb_build_object('items', ARRAY[$txt$Jelaskan perbedaan energi kinetik dan energi potensial beserta contohnya!$txt$,$txt$Hitung energi potensial buah kelapa 1,5 kg di pohon setinggi 8 m (g = 10 m/s^2)! Kunci: Ep = 1,5 x 10 x 8 = 120 joule.$txt$,$txt$Sebutkan 3 perubahan bentuk energi yang terjadi saat kamu menyalakan senter! Kunci: energi kimia (baterai) menjadi energi listrik, lalu menjadi energi cahaya.$txt$]::text[]));
  INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, status, created_by, updated_by) VALUES (gen_random_uuid(), 'SCH-SD-IPS13-001', 'd3333333-3333-3333-3333-333333333333', $txt$IPS Kelas 4: Sumber Daya Alam Indonesia$txt$, 'ips-kelas-4-sumber-daya-alam', $txt$Materi IPS kelas 4: pengertian sumber daya alam, jenisnya, dan cara menjaganya.$txt$, 'id', 7, 'Madevi', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'DRAFT', 'f7125028-187e-44e0-b95b-88b69b8d5c9a', 'f7125028-187e-44e0-b95b-88b69b8d5c9a') ON CONFLICT (business_code) DO NOTHING RETURNING id INTO v_sch_sd_ips13_001;
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_sch_sd_ips13_001, 'HEADING', 0, jsonb_build_object('text', $txt$Tujuan Pembelajaran$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_sch_sd_ips13_001, 'LIST', 1, jsonb_build_object('items', ARRAY[$txt$Menjelaskan pengertian sumber daya alam$txt$,$txt$Membedakan sumber daya alam yang dapat diperbarui dan tidak dapat diperbarui$txt$,$txt$Menyebutkan contoh sumber daya alam di Indonesia$txt$,$txt$Menjelaskan cara menjaga kelestarian sumber daya alam$txt$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_sch_sd_ips13_001, 'HEADING', 2, jsonb_build_object('text', $txt$Apa Itu Sumber Daya Alam$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_sch_sd_ips13_001, 'PARAGRAPH', 3, jsonb_build_object('text', $txt$Sumber daya alam adalah segala sesuatu yang berasal dari alam dan dapat dimanfaatkan manusia untuk memenuhi kebutuhan hidup. Contohnya: air, tanah, udara, tumbuhan, hewan, batu bara, dan minyak bumi. Indonesia sangat kaya sumber daya alam — dari hutan tropis hingga tambang.$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_sch_sd_ips13_001, 'HEADING', 4, jsonb_build_object('text', $txt$Dapat Diperbarui dan Tidak Dapat Diperbarui$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_sch_sd_ips13_001, 'LIST', 5, jsonb_build_object('items', ARRAY[$txt$Dapat diperbarui: bisa pulih kembali bila dikelola dengan baik — air, tanah, tumbuhan, hewan, sinar Matahari, angin.$txt$,$txt$Tidak dapat diperbarui: jumlahnya terbatas dan akan habis — batu bara, minyak bumi, gas alam, emas, timah.$txt$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_sch_sd_ips13_001, 'HEADING', 6, jsonb_build_object('text', $txt$Cara Menjaga Kelestariannya$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_sch_sd_ips13_001, 'LIST', 7, jsonb_build_object('items', ARRAY[$txt$Tidak menebang pohon sembarangan; lakukan reboisasi.$txt$,$txt$Hemat air dan listrik setiap hari.$txt$,$txt$Tidak membuang sampah ke sungai dan laut.$txt$,$txt$Mengurangi, memakai ulang, dan mendaur ulang sampah (3R).$txt$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_sch_sd_ips13_001, 'HEADING', 8, jsonb_build_object('text', $txt$Latihan Soal$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_sch_sd_ips13_001, 'LIST', 9, jsonb_build_object('items', ARRAY[$txt$Apa yang dimaksud dengan sumber daya alam? Berikan 3 contoh! Kunci: segala sesuatu dari alam yang dapat dimanfaatkan manusia, contoh: air, tanah, tumbuhan.$txt$,$txt$Sebutkan perbedaan SDA yang dapat diperbarui dan tidak dapat diperbarui beserta contohnya! Kunci: dapat diperbarui pulih kembali (air, tumbuhan); tidak dapat diperbarui terbatas dan akan habis (batu bara, minyak bumi).$txt$,$txt$Tuliskan 3 cara menjaga kelestarian SDA di lingkungan sekitarmu! Kunci: hemat air, tidak membuang sampah sembarangan, menanam pohon.$txt$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_sch_sd_ips13_001, 'HEADING', 10, jsonb_build_object('text', $txt$Pesan Moral$txt$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_sch_sd_ips13_001, 'PARAGRAPH', 11, jsonb_build_object('text', $txt$Alam memberi kita segalanya — air, makanan, dan udara. Anak yang baik menjaga alam, bukan merusaknya. Mulailah dari hal kecil: hemat air dan buang sampah pada tempatnya.$txt$));
